    notes: 'French fashion house founded by Madeleine Vionnet, whose bias cutting and geometric construction helped redefine how fabric moves around the body. Fluid dresses, subtle draping and an emphasis on movement underpin its historical identity. The original couture house closed in 1939; later revivals reinterpreted its archive through ready-to-wear. ChimHaeres acquired the brand in 2023; Paris marks its founding couture identity.',
    sources: ['https://www.vam.ac.uk/articles/madeleine-vionnet-an-introduction', 'https://collections.madparis.fr/en/document/vion-1-8/652fe82d367c571c410af2a5?pos=9', 'https://portal.chimerainvestment.com/website/en/releases/171-id.pdf'],
