    sources: ['https://www.gapinc.com/en-us/about/history', 'https://www.gapinc.com/es-us/articles/2025/09/the-next-chapter-in-gap-s-legacy-of-iconic-campaig', 'https://investors.gapinc.com/press-releases/news-details/2020/Kanye-West-Teams-with-Gap/default.aspx', 'https://www.vogue.com/article/ye-gap-engineered-by-balenciaga'],
