    notes: 'London clothing label built around Nick Wakeman’s idea of a modular wardrobe. Generous trousers, clean shirts and substantial outerwear use carefully chosen fabrics and controlled proportions to create an understated silhouette. The collections place texture, movement and the relationship between separate garments ahead of prominent decoration, extending a consistent approach across womenswear and menswear.',
